namespace Ray.Automerge.Repository.Storage;

/// <summary>
/// In-memory storage adapter for testing and ephemeral repositories.
/// </summary>
/// <remarks>
/// This adapter stores all data in memory using a dictionary. Data is lost when the adapter
/// is disposed or when the application terminates. Use this adapter for:
/// <list type="bullet">
/// <item>Unit and integration testing</item>
/// <item>Temporary documents that don't require persistence</item>
/// <item>Prototyping and development</item>
/// </list>
/// <para>
/// This adapter is thread-safe and supports concurrent operations.
/// </para>
/// </remarks>
[PublicAPI]
public sealed class InMemoryStorageAdapter : IStorageAdapter, IDisposable
{
  readonly Dictionary<string, byte[]> _storage = [];
  readonly SemaphoreSlim _lock = new(1, 1);
  bool _isDisposed;


  /// <summary>
  /// Gets the number of keys currently stored.
  /// </summary>
  /// <remarks>
  /// This property is useful for testing and debugging.
  /// </remarks>
  public int Count
  {
    get
    {
      ThrowIfDisposed();
      return _storage.Count;
    }
  }



  /// <summary>
  /// 
  /// Disposes this storage adapter and clears all data.
  /// </summary>
  public void Dispose()
  {
    if(_isDisposed)
      return;

    _isDisposed = true;
    _storage.Clear();
    _lock.Dispose();
  }


  public async Task<byte[]?> Load(StorageKey key)
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      var keyString = key.ToDebugString();
      if(!_storage.TryGetValue(keyString, out var data))
        return null;

      // Copy the data to ensure isolation
      var copy = new byte[data.Length];
      Array.Copy(data, copy, data.Length);
      return copy;
    }
    finally
    {
      _lock.Release();
    }
  }

  public async Task Save(StorageKey key, byte[] data)
  {
    ThrowIfDisposed();

    if(data is null)
      throw new ArgumentNullException(nameof(data));

    await _lock.WaitAsync();
    try
    {
      var keyString = key.ToDebugString();
      // Copy the data to ensure isolation
      var copy = new byte[data.Length];
      Array.Copy(data, copy, data.Length);
      _storage[keyString] = copy;
    }
    finally
    {
      _lock.Release();
    }
  }

  public async Task Remove(StorageKey key)
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      var keyString = key.ToDebugString();
      _storage.Remove(keyString);
    }
    finally
    {
      _lock.Release();
    }
  }

  public async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      var results = new List<Chunk>();

      foreach(var kvp in _storage)
      {
        // Parse the key back to StorageKey
        var components = kvp.Key.Split('/');
        var storageKey = new StorageKey(components);

        // Check if it matches the prefix
        if(storageKey.StartsWith(keyPrefix))
        {
          // Copy the data to ensure isolation
          var dataCopy = new byte[kvp.Value.Length];
          Array.Copy(kvp.Value, dataCopy, kvp.Value.Length);
          results.Add(new Chunk(storageKey, dataCopy));
        }
      }

      return results;
    }
    finally
    {
      _lock.Release();
    }
  }

  public async Task RemoveRange(StorageKey keyPrefix)
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      // Find all keys that match the prefix
      var keysToRemove = new List<string>();

      foreach(var kvp in _storage)
      {
        var components = kvp.Key.Split('/');
        var storageKey = new StorageKey(components);

        if(storageKey.StartsWith(keyPrefix))
        {
          keysToRemove.Add(kvp.Key);
        }
      }

      // Remove them
      foreach(var key in keysToRemove)
      {
        _storage.Remove(key);
      }
    }
    finally
    {
      _lock.Release();
    }
  }

  public async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      var results = new List<ChunkInfo>();

      foreach(var kvp in _storage)
      {
        var components = kvp.Key.Split('/');
        var storageKey = new StorageKey(components);

        if(storageKey.StartsWith(keyPrefix))
        {
          results.Add(new ChunkInfo(storageKey, kvp.Value.Length));
        }
      }

      return results;
    }
    finally
    {
      _lock.Release();
    }
  }

  /// <summary>
  /// Clears all data from storage.
  /// </summary>
  /// <remarks>
  /// This method is useful for testing scenarios where you need to reset storage state.
  /// </remarks>
  public async Task Clear()
  {
    ThrowIfDisposed();

    await _lock.WaitAsync();
    try
    {
      _storage.Clear();
    }
    finally
    {
      _lock.Release();
    }
  }



  void ThrowIfDisposed()
  {
    if(_isDisposed)
      throw new ObjectDisposedException(nameof(InMemoryStorageAdapter));
  }

}

/**
 * @packageDocumentation
 * A `StorageAdapter` which stores data in the local filesystem
 */

import {
  Chunk,
  StorageAdapterInterface,
  type StorageKey,
} from "@automerge/automerge-repo/slim"
import fs from "fs"
import path from "path"
import { rimraf } from "rimraf"

export class NodeFSStorageAdapter implements StorageAdapterInterface {
  private baseDirectory: string
  private cache: { [key: string]: Uint8Array } = {}

  /**
   * @param baseDirectory - The path to the directory to store data in. Defaults to "./automerge-repo-data".
   */
  constructor(baseDirectory = "automerge-repo-data") {
    this.baseDirectory = baseDirectory
  }

  async load(keyArray: StorageKey): Promise<Uint8Array | undefined> {
    const key = getKey(keyArray)
    if (this.cache[key]) return this.cache[key]

    const filePath = this.getFilePath(keyArray)

    try {
      const fileContent = await fs.promises.readFile(filePath)
      return new Uint8Array(fileContent)
    } catch (error: any) {
      // don't throw if file not found
      if (error.code === "ENOENT") return undefined
      throw error
    }
  }

  async save(keyArray: StorageKey, binary: Uint8Array): Promise<void> {
    const key = getKey(keyArray)
    this.cache[key] = binary

    const filePath = this.getFilePath(keyArray)

    await fs.promises.mkdir(path.dirname(filePath), { recursive: true })
    await fs.promises.writeFile(filePath, binary)
  }

  async remove(keyArray: string[]): Promise<void> {
    // remove from cache
    delete this.cache[getKey(keyArray)]
    // remove from disk
    const filePath = this.getFilePath(keyArray)
    try {
      await fs.promises.unlink(filePath)
    } catch (error: any) {
      // don't throw if file not found
      if (error.code !== "ENOENT") throw error
    }
  }

  async loadRange(keyPrefix: StorageKey): Promise<Chunk[]> {
    /* This whole function does a bunch of gratuitious string manipulation
       and could probably be simplified. */

    const dirPath = this.getFilePath(keyPrefix)

    // Get the list of all cached keys that match the prefix
    const cachedKeys = this.cachedKeys(keyPrefix)

    // Read filenames from disk
    const diskFiles = await walkdir(dirPath)

    // The "keys" in the cache don't include the baseDirectory.
    // We want to de-dupe with the cached keys so we'll use getKey to normalize them.
    const diskKeys: string[] = diskFiles.map((fileName: string) => {
      const k = getKey([path.relative(this.baseDirectory, fileName)])
      return k.slice(0, 2) + k.slice(3)
    })

    // Combine and deduplicate the lists of keys
    const allKeys = [...new Set([...cachedKeys, ...diskKeys])]

    // Load all files
    const chunks = await Promise.all(
      allKeys.map(async keyString => {
        const key: StorageKey = keyString.split(path.sep)
        const data = await this.load(key)
        return { data, key }
      })
    )

    return chunks
  }

  async removeRange(keyPrefix: string[]): Promise<void> {
    // remove from cache
    this.cachedKeys(keyPrefix).forEach(key => delete this.cache[key])

    // remove from disk
    const dirPath = this.getFilePath(keyPrefix)
    await rimraf(dirPath)
  }

  private cachedKeys(keyPrefix: string[]): string[] {
    const cacheKeyPrefixString = getKey(keyPrefix)
    return Object.keys(this.cache).filter(key =>
      key.startsWith(cacheKeyPrefixString)
    )
  }

  private getFilePath(keyArray: string[]): string {
    const [firstKey, ...remainingKeys] = keyArray
    return path.join(
      this.baseDirectory,
      firstKey.slice(0, 2),
      firstKey.slice(2),
      ...remainingKeys
    )
  }
}

// HELPERS

const getKey = (key: StorageKey): string => path.join(...key)

/** returns all files in a directory, recursively  */
const walkdir = async (dirPath: string): Promise<string[]> => {
  try {
    const entries = await fs.promises.readdir(dirPath, { withFileTypes: true })
    const files = await Promise.all(
      entries.map(entry => {
        const subpath = path.resolve(dirPath, entry.name)
        return entry.isDirectory() ? walkdir(subpath) : subpath
      })
    )
    return files.flat()
  } catch (error: any) {
    // don't throw if directory not found
    if (error.code === "ENOENT") return []
    throw error
  }
}

import { StorageKey, Chunk } from "./types.js"

/** A storage adapter represents some way of storing binary data for a {@link Repo}
 *
 * @remarks
 * `StorageAdapter`s provide a key/value storage interface. The keys are arrays of strings
 * ({@link StorageKey}) and the values are binary blobs.
 */
export interface StorageAdapterInterface {
  /** Load the single value corresponding to `key` */
  load(key: StorageKey): Promise<Uint8Array | undefined>

  /** Save the value `data` to the key `key` */
  save(key: StorageKey, data: Uint8Array): Promise<void>

  /** Remove the value corresponding to `key` */
  remove(key: StorageKey): Promise<void>

  /**
   * Load all values with keys that start with `keyPrefix`.
   *
   * @remarks
   * The `keyprefix` will match any key that starts with the given array. For example:
   * - `[documentId, "incremental"]` will match all incremental saves
   * - `[documentId]` will match all data for a given document.
   *
   * Be careful! `[documentId]` would also match something like `[documentId, "syncState"]`! We
   * aren't using this yet but keep it in mind.)
   */
  loadRange(keyPrefix: StorageKey): Promise<Chunk[]>

  /** Remove all values with keys that start with `keyPrefix` */
  removeRange(keyPrefix: StorageKey): Promise<void>
}

namespace Ray.Automerge.Repository.Storage;

/// <summary>
/// Interface for storage adapters that persist Automerge documents and sync state.
/// Implementations can target any backend: memory, file system, database, cloud storage, etc.
/// </summary>
/// <remarks>
/// <para>
/// Storage adapters must be thread-safe and support concurrent operations.
/// Multiple calls to the same or different keys may occur simultaneously.
/// </para>
/// <para>
/// Keys use a hierarchical structure (e.g., [documentId, "snapshot", hash]) to organize data.
/// Use <see cref="StorageKey"/> factory methods to create properly formatted keys.
/// </para>
/// <example>
/// Example implementation using in-memory dictionary:
/// <code>
/// public class InMemoryAdapter : IStorageAdapter
/// {
///     private readonly Dictionary&lt;string, byte[]&gt; _storage = new();
///
///     public Task&lt;byte[]?&gt; Load(StorageKey key)
///     {
///         var keyStr = key.ToDebugString();
///         return Task.FromResult(_storage.TryGetValue(keyStr, out var data) ? data : null);
///     }
///
///     // ... implement other methods
/// }
/// </code>
/// </example>
/// </remarks>
[PublicAPI]
public interface IStorageAdapter
{
    /// <summary>
    /// Loads data for a single storage key.
    /// </summary>
    /// <param name="key">The storage key to load.</param>
    /// <returns>The data if found; null if the key does not exist.</returns>
    /// <remarks>
    /// This method should return null (not throw an exception) when the key is not found.
    /// </remarks>
    Task<byte[]?> Load(StorageKey key);

    /// <summary>
    /// Saves data for a single storage key.
    /// </summary>
    /// <param name="key">The storage key to save.</param>
    /// <param name="data">The data to save.</param>
    /// <remarks>
    /// If the key already exists, its data should be replaced.
    /// Implementations should copy the data array if they need to retain it beyond the async operation.
    /// </remarks>
    Task Save(StorageKey key, byte[] data);

    /// <summary>
    /// Removes data for a single storage key.
    /// </summary>
    /// <param name="key">The storage key to remove.</param>
    /// <remarks>
    /// This method should succeed silently if the key does not exist.
    /// </remarks>
    Task Remove(StorageKey key);

    /// <summary>
    /// Loads all chunks matching a key prefix (e.g., all chunks for a document).
    /// </summary>
    /// <param name="keyPrefix">The key prefix to match.</param>
    /// <returns>All matching chunks. Returns an empty list if no matches are found.</returns>
    /// <remarks>
    /// Use <see cref="StorageKey.StartsWith"/> to determine if a key matches the prefix.
    /// For example, prefix [documentId] matches [documentId, "snapshot", hash] and [documentId, "incremental", hash].
    /// </remarks>
    /// <example>
    /// <code>
    /// var prefix = new StorageKey(new[] { documentId });
    /// var chunks = await adapter.LoadRange(prefix);
    /// // Returns all chunks with keys starting with [documentId]
    /// </code>
    /// </example>
    Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix);

    /// <summary>
    /// Removes all keys matching a key prefix.
    /// </summary>
    /// <param name="keyPrefix">The key prefix to match.</param>
    /// <remarks>
    /// Use <see cref="StorageKey.StartsWith"/> to determine if a key matches the prefix.
    /// This method should succeed silently if no matching keys are found.
    /// </remarks>
    Task RemoveRange(StorageKey keyPrefix);

    /// <summary>
    /// Gets metadata about all chunks matching a key prefix (without loading data).
    /// Used for storage optimization decisions.
    /// </summary>
    /// <param name="keyPrefix">The key prefix to match.</param>
    /// <returns>Metadata for all matching chunks. Returns an empty list if no matches are found.</returns>
    /// <remarks>
    /// This method is used by the storage subsystem to determine if compaction is needed.
    /// Implementations can optimize this by returning size metadata without loading full chunk data.
    /// </remarks>
    Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix);
}

namespace Ray.Automerge.Repository.Storage;

/// <summary>
/// Abstract base class for storage adapters providing common functionality.
/// </summary>
/// <remarks>
/// This base class provides a default implementation of <see cref="GetChunkInfo"/>
/// that loads the full range and extracts metadata. Derived classes can override
/// this method for more efficient implementations that don't require loading full data.
/// </remarks>
[PublicAPI]
public abstract class StorageAdapterBase : IStorageAdapter
{
  /// <inheritdoc />
  public abstract Task<byte[]?> Load(StorageKey key);

  /// <inheritdoc />
  public abstract Task Save(StorageKey key, byte[] data);

  /// <inheritdoc />
  public abstract Task Remove(StorageKey key);

  /// <inheritdoc />
  public abstract Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix);

  /// <inheritdoc />
  public abstract Task RemoveRange(StorageKey keyPrefix);

  /// <summary>
  /// Gets metadata about all chunks matching a key prefix.
  /// Default implementation loads the full range and extracts metadata.
  /// Override this method for more efficient implementations that avoid loading full data.
  /// </summary>
  /// <param name="keyPrefix">The key prefix to match.</param>
  /// <returns>Metadata for all matching chunks.</returns>
  public virtual async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
  {
    var chunks = await LoadRange(keyPrefix);
    return chunks.Select(c => new ChunkInfo(c.Key, c.Data.Length)).ToList();
  }
}

