 48→    ) -> Result<Self, AutomergeFfiError> {
 49→        result_to_ffi(|| {
 50→            let hashes = convert_heads(heads);
 51→            let forked = doc
 52→                .inner
 53→                .fork_at(&hashes)
 54→                .map_err(AutomergeFfiError::from)?;
 55→            Ok(Self { inner: forked })
 56→        })
 57→    }
