151→    pub fn apply_changes(
152→        &mut self,
153→        changes: ffi::Slice<'_, ChangeBytes>,
154→    ) -> Result<(), AutomergeFfiError> {
155→        result_to_ffi(|| {
156→            let parsed: Vec<Change> = changes
157→                .as_slice()
158→                .iter()
159→                .map(|c| {
160→                    let bytes: Vec<u8> = c.bytes.clone().into();
161→                    Change::try_from(bytes.as_slice()).map_err(AutomergeFfiError::from)
162→                })
163→                .collect::<std::result::Result<_, _>>()?;
164→            self.inner
165→                .apply_changes(parsed)
166→                .map_err(AutomergeFfiError::from)?;
167→            Ok(())
168→        })
