190→    pub fn get_changes(
191→        &mut self,
192→        have: ffi::Slice<'_, ChangeHashBytes>,
193→    ) -> Result<ffi::Vec<ChangeBytes>, AutomergeFfiError> {
194→        result_to_ffi(|| {
195→            let have_hashes: Vec<ChangeHash> = have
196→                .as_slice()
197→                .iter()
198→                .copied()
199→                .map(ChangeHash::from)
200→                .collect();
201→            let changes = self.inner.get_changes(&have_hashes);
202→            let result: Vec<ChangeBytes> = changes
203→                .into_iter()
204→                .map(|change| ChangeBytes::from(change.raw_bytes().to_vec()))
205→                .collect();
206→            Ok(result.into())
207→        })
208→    }
