660→            let root = ObjId::Root;
661→            let hydrated = self
662→                .inner
663→                .hydrate(&root, None)
664→                .map_err(AutomergeFfiError::from)?;
665→            let json = value_to_json(&hydrated);
666→            let serialized = serde_json::to_string(&json).map_err(AutomergeFfiError::from)?;
667→            Ok(serialized.into())
668→        })
669→    }
670→
671→    pub fn hydrate_json_at_heads(
672→        &self,
673→        heads: ffi::Slice<'_, ChangeHashBytes>,
674→    ) -> Result<ffi::String, AutomergeFfiError> {
675→        result_to_ffi(|| {
676→            let root = ObjId::Root;
677→            let hashes = convert_heads(heads);
678→            let hydrated = self
679→                .inner
680→                .hydrate(&root, Some(&hashes))
681→                .map_err(AutomergeFfiError::from)?;
682→            let json = value_to_json(&hydrated);
683→            let serialized = serde_json::to_string(&json).map_err(AutomergeFfiError::from)?;
684→            Ok(serialized.into())
685→        })
686→    }
687→
688→    pub fn sync_generate_message(
689→        &mut self,
690→        state: &mut crate::sync::AutomergeSyncState,
691→    ) -> Result<ffi::Option<ByteArray>, AutomergeFfiError> {
692→        result_to_ffi(|| {
693→            #[allow(unused_mut)]
694→            let mut sync_doc = self.inner.sync();
695→            let maybe_message = sync_doc.generate_sync_message(&mut state.inner);
696→            Ok(match maybe_message {
697→                Some(message) => {
698→                    let encoded = message.encode();
699→                    ffi::Option::Some(ByteArray::from_vec(encoded))
700→                }
701→                None => ffi::Option::None,
702→            })
703→        })
704→    }
705→
706→    pub fn sync_receive_message(
707→        &mut self,
708→        state: &mut crate::sync::AutomergeSyncState,
709→        message: ByteArray,
710→    ) -> Result<(), AutomergeFfiError> {
711→        result_to_ffi(|| {
712→            let bytes: Vec<u8> = message.into();
713→            let message = automerge::sync::Message::decode(bytes.as_slice())
714→                .map_err(|err| AutomergeFfiError::invalid_change(err.to_string()))?;
715→            #[allow(unused_mut)]
716→            let mut sync_doc = self.inner.sync();
717→            sync_doc
718→                .receive_sync_message(&mut state.inner, message)
719→                .map_err(AutomergeFfiError::from)?;
720→            Ok(())
721→        })
722→    }
723→
724→    pub fn get_change_metadata(
725→        &mut self,
726→        hash: ChangeHashBytes,
727→    ) -> Result<ffi::Option<DecodedChange>, AutomergeFfiError> {
728→        result_to_ffi(|| {
729→            let change_hash = ChangeHash::from(hash);
730→            match self.inner.get_change_meta_by_hash(&change_hash) {
731→                Some(metadata) => {
732→                    let decoded = DecodedChange::from_change_metadata(metadata);
733→                    Ok(ffi::Option::Some(decoded))
734→                }
735→                None => Ok(ffi::Option::None),
736→            }
737→        })
738→    }
739→}
740→
741→fn convert_heads(heads: ffi::Slice<'_, ChangeHashBytes>) -> Vec<ChangeHash> {
742→    heads
743→        .as_slice()
744→        .iter()
745→        .copied()
746→        .map(ChangeHash::from)
747→        .collect()
748→}
749→
750→fn value_to_json(value: &automerge::hydrate::Value) -> serde_json::Value {
751→    use automerge::hydrate::Value as HydrateValue;
752→    use automerge::ScalarValue;
753→    match value {
754→        HydrateValue::Scalar(scalar) => match scalar {
755→            ScalarValue::Null => serde_json::Value::Null,
756→            ScalarValue::Boolean(v) => serde_json::Value::Bool(*v),
757→            ScalarValue::Int(v) => serde_json::Value::Number((*v).into()),
758→            ScalarValue::Uint(v) => serde_json::Value::Number((*v).into()),
759→            ScalarValue::F64(v) => serde_json::Number::from_f64(*v)
760→                .map(serde_json::Value::Number)
761→                .unwrap_or(serde_json::Value::Null),
762→            ScalarValue::Str(v) => serde_json::Value::String(v.to_string()),
763→            ScalarValue::Bytes(v) => serde_json::Value::String(BASE64_STANDARD.encode(v)),
764→            ScalarValue::Counter(v) => serde_json::json!({ "type": "counter", "value": *v }),
765→            ScalarValue::Timestamp(v) => {
766→                serde_json::json!({ "type": "timestamp", "value": *v })
767→            }
768→            ScalarValue::Unknown { bytes, .. } => {
769→                serde_json::json!({ "type": "unknown", "value": BASE64_STANDARD.encode(bytes) })
770→            }
771→        },
772→        HydrateValue::Map(map) => {
773→            let mut obj = serde_json::Map::new();
774→            for (key, map_value) in map.iter() {
775→                obj.insert(key.clone(), value_to_json(&map_value.value));
776→            }
777→            serde_json::Value::Object(obj)
778→        }
779→        HydrateValue::List(list) => {
780→            let array = list
781→                .iter()
782→                .map(|item| value_to_json(&item.value))
783→                .collect::<Vec<_>>();
784→            serde_json::Value::Array(array)
785→        }
786→        HydrateValue::Text(text) => {
787→            let s: String = text.into();
788→            serde_json::Value::String(s)
789→        }
790→    }
791→}
