102→    pub fn to_bytes(&self) -> [u8; 32] {
103→        let mut bytes = [0_u8; 32];
104→        bytes[0..8].copy_from_slice(&self.part1.to_le_bytes());
105→        bytes[8..16].copy_from_slice(&self.part2.to_le_bytes());
106→        bytes[16..24].copy_from_slice(&self.part3.to_le_bytes());
107→        bytes[24..32].copy_from_slice(&self.part4.to_le_bytes());
