#[ffi_type]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AutomergePatchActionKind {
    PutMap,
    PutSeq,
    Insert,
    SpliceText,
    Increment,
    Conflict,
    DeleteMap,
    DeleteSeq,
    Mark,
}

#[ffi_type]
#[derive(Clone, Debug)]
pub struct AutomergePatchAction {
    pub kind: AutomergePatchActionKind,
    pub key: ffi::Option<ffi::String>,
    pub index: u64,
    pub value: ffi::Option<AutomergeValue>,
    pub value_object_id: ffi::Option<AutomergeObjId>,
    pub conflict: bool,
    pub inserted: ffi::Vec<AutomergeInsertEntry>,
    pub text: ffi::Option<ffi::String>,
    pub active_marks: ffi::Vec<AutomergeMarkData>,
    pub marks: ffi::Vec<AutomergeMarkSpan>,
    pub prop: ffi::Option<AutomergeProp>,
    pub length: u64,
    pub increment_value: i64,
}

impl AutomergePatchAction {
    fn from_patch_action(action: PatchAction) -> Self {
        match action {
            PatchAction::PutMap {
                key,
                value,
                conflict,
            } => {
                let (value_variant, object_id) = value;
                let value_object_id = if matches!(&value_variant, Value::Object(_)) {
                    ffi::Option::Some(AutomergeObjId::from(object_id.clone()))
                } else {
                    ffi::Option::None
                };
                Self {
                    kind: AutomergePatchActionKind::PutMap,
                    key: ffi::Option::Some(key.into()),
                    index: 0,
                    value: ffi::Option::Some(AutomergeValue::from(value_variant.clone())),
                    value_object_id,
                    conflict,
                    inserted: ffi::Vec::from_vec(Vec::new()),
                    text: ffi::Option::None,
                    active_marks: ffi::Vec::from_vec(Vec::new()),
                    marks: ffi::Vec::from_vec(Vec::new()),
                    prop: ffi::Option::None,
                    length: 0,
                    increment_value: 0,
                }
            }
            PatchAction::PutSeq {
                index,
                value,
                conflict,
            } => {
                let (value_variant, object_id) = value;
                let value_object_id = if matches!(&value_variant, Value::Object(_)) {
                    ffi::Option::Some(AutomergeObjId::from(object_id.clone()))
                } else {
                    ffi::Option::None
                };
                Self {
                    kind: AutomergePatchActionKind::PutSeq,
                    key: ffi::Option::None,
                    index: index as u64,
                    value: ffi::Option::Some(AutomergeValue::from(value_variant.clone())),
                    value_object_id,
                    conflict,
                    inserted: ffi::Vec::from_vec(Vec::new()),
                    text: ffi::Option::None,
                    active_marks: ffi::Vec::from_vec(Vec::new()),
                    marks: ffi::Vec::from_vec(Vec::new()),
                    prop: ffi::Option::None,
                    length: 0,
                    increment_value: 0,
                }
            }
            PatchAction::Insert { index, values } => {
                let entries: Vec<AutomergeInsertEntry> = values
                    .iter()
                    .map(AutomergeInsertEntry::from_tuple)
                    .collect();
                Self {
                    kind: AutomergePatchActionKind::Insert,
                    key: ffi::Option::None,
                    index: index as u64,
                    value: ffi::Option::None,
                    conflict: false,
                    value_object_id: ffi::Option::None,
                    inserted: entries.into(),
                    text: ffi::Option::None,
                    active_marks: ffi::Vec::from_vec(Vec::new()),
                    marks: ffi::Vec::from_vec(Vec::new()),
                    prop: ffi::Option::None,
                    length: 0,
                    increment_value: 0,
                }
            }
            PatchAction::SpliceText {
                index,
                value,
                marks,
            } => {
                let text_value = ffi::Option::Some(value.make_string().into());
                let active_marks_vec: Vec<AutomergeMarkData> = match marks {
                    Some(mark_set) => mark_set
                        .iter()
                        .map(|(name, value)| AutomergeMarkData::from_mark_entry(name, value))
                        .collect(),
                    None => Vec::new(),
                };

                Self {
                    kind: AutomergePatchActionKind::SpliceText,
                    key: ffi::Option::None,
                    index: index as u64,
                    value: ffi::Option::None,
                    conflict: false,
                    value_object_id: ffi::Option::None,
                    inserted: ffi::Vec::from_vec(Vec::new()),
                    text: text_value,
                    active_marks: active_marks_vec.into(),
                    marks: ffi::Vec::from_vec(Vec::new()),
                    prop: ffi::Option::None,
                    length: 0,
                    increment_value: 0,
                }
            }
            PatchAction::Increment { prop, value } => Self {
                kind: AutomergePatchActionKind::Increment,
                key: ffi::Option::None,
                index: 0,
                value: ffi::Option::None,
                value_object_id: ffi::Option::None,
                conflict: false,
                inserted: ffi::Vec::from_vec(Vec::new()),
                text: ffi::Option::None,
                active_marks: ffi::Vec::from_vec(Vec::new()),
                marks: ffi::Vec::from_vec(Vec::new()),
                prop: ffi::Option::Some(AutomergeProp::from(prop)),
                length: 0,
                increment_value: value,
            },
            PatchAction::Conflict { prop } => Self {
                kind: AutomergePatchActionKind::Conflict,
                key: ffi::Option::None,
                index: 0,
                value: ffi::Option::None,
                value_object_id: ffi::Option::None,
                conflict: false,
                inserted: ffi::Vec::from_vec(Vec::new()),
                text: ffi::Option::None,
                active_marks: ffi::Vec::from_vec(Vec::new()),
                marks: ffi::Vec::from_vec(Vec::new()),
                prop: ffi::Option::Some(AutomergeProp::from(prop)),
                length: 0,
                increment_value: 0,
            },
            PatchAction::DeleteMap { key } => Self {
                kind: AutomergePatchActionKind::DeleteMap,
                key: ffi::Option::Some(key.into()),
                index: 0,
                value: ffi::Option::None,
                value_object_id: ffi::Option::None,
                conflict: false,
                inserted: ffi::Vec::from_vec(Vec::new()),
                text: ffi::Option::None,
                active_marks: ffi::Vec::from_vec(Vec::new()),
                marks: ffi::Vec::from_vec(Vec::new()),
                prop: ffi::Option::None,
                length: 0,
                increment_value: 0,
            },
            PatchAction::DeleteSeq { index, length } => Self {
                kind: AutomergePatchActionKind::DeleteSeq,
                key: ffi::Option::None,
                index: index as u64,
                value: ffi::Option::None,
                value_object_id: ffi::Option::None,
                conflict: false,
                inserted: ffi::Vec::from_vec(Vec::new()),
                text: ffi::Option::None,
                active_marks: ffi::Vec::from_vec(Vec::new()),
                marks: ffi::Vec::from_vec(Vec::new()),
                prop: ffi::Option::None,
                length: length as u64,
                increment_value: 0,
            },
            PatchAction::Mark { marks } => {
                let converted: Vec<AutomergeMarkSpan> =
                    marks.iter().map(AutomergeMarkSpan::from).collect();
                Self {
                    kind: AutomergePatchActionKind::Mark,
                    key: ffi::Option::None,
                    index: 0,
                    value: ffi::Option::None,
                    value_object_id: ffi::Option::None,
                    conflict: false,
                    inserted: ffi::Vec::from_vec(Vec::new()),
                    text: ffi::Option::None,
                    active_marks: ffi::Vec::from_vec(Vec::new()),
                    marks: converted.into(),
                    prop: ffi::Option::None,
                    length: 0,
                    increment_value: 0,
                }
            }
        }
    }
}

#[ffi_type]
#[derive(Clone, Debug)]
pub struct AutomergePatchPathElement {
    pub object_id: AutomergeObjId,
    pub prop: AutomergeProp,
}

impl From<(ObjId, Prop)> for AutomergePatchPathElement {
    fn from(value: (ObjId, Prop)) -> Self {
        Self {
            object_id: value.0.into(),
            prop: AutomergeProp::from(value.1),
        }
    }
}

#[ffi_type]
#[derive(Clone, Debug)]
pub struct AutomergePatch {
    pub object_id: AutomergeObjId,
    pub path: ffi::Vec<AutomergePatchPathElement>,
    pub action: AutomergePatchAction,
}

impl From<Patch> for AutomergePatch {
    fn from(value: Patch) -> Self {
        let path: Vec<AutomergePatchPathElement> = value
            .path
            .into_iter()
            .map(AutomergePatchPathElement::from)
            .collect();
        Self {
            object_id: value.obj.into(),
            path: path.into(),
            action: AutomergePatchAction::from_patch_action(value.action),
        }
    }
}

#[ffi_type]
#[derive(Clone, Debug)]
pub struct DecodedChange {
    pub hash: ChangeHashBytes,
    pub actor: ffi::String,
    pub seq: u64,
    pub timestamp: i64,
    pub message: ffi::Option<ffi::String>,
    pub deps: ffi::Vec<ChangeHashBytes>,
}

impl DecodedChange {
    pub fn from_change_metadata(metadata: automerge::ChangeMetadata<'_>) -> Self {
        let hash = ChangeHashBytes::from(&metadata.hash);
        let actor = metadata.actor.to_hex_string().into();
        let seq = metadata.seq;
        let timestamp = metadata.timestamp;
        let message = match &metadata.message {
            Some(msg) => ffi::Option::Some(msg.to_string().into()),
            None => ffi::Option::None,
        };
        let deps: Vec<ChangeHashBytes> = metadata
            .deps
            .iter()
            .map(|h| ChangeHashBytes::from(h))
            .collect();

        Self {
            hash,
            actor,
            seq,
            timestamp,
            message,
            deps: deps.into(),
        }
    }
}

namespace Ray.Automerge.Repository.Storage;

/// <summary>
/// Represents a hierarchical storage key in the format [component1, component2, ...].
/// Used to organize documents, snapshots, incremental changes, and sync state.
/// </summary>
[PublicAPI]
public readonly record struct StorageKey
{
  /// <summary>
  /// Gets the hierarchical components of this storage key.
  /// </summary>
  public IReadOnlyList<string> Components { get; init; }

  /// <summary>
  /// Initializes a new instance of <see cref="StorageKey"/> with the specified components.
  /// </summary>
  /// <param name="components">The hierarchical key components.</param>
  public StorageKey(IReadOnlyList<string> components)
  {
    Components = components ?? Array.Empty<string>();
  }

  /// <summary>
  /// Creates a storage key for a document snapshot.
  /// Format: [documentId, "snapshot", snapshotHash]
  /// </summary>
  /// <param name="documentId">The document identifier.</param>
  /// <param name="snapshotHash">The hash of the snapshot (typically from document heads).</param>
  /// <returns>A storage key for the snapshot.</returns>
  public static StorageKey DocumentSnapshot(string documentId, string snapshotHash)
  {
    return new StorageKey(new[] { documentId, "snapshot", snapshotHash });
  }

  /// <summary>
  /// Creates a storage key for an incremental document change.
  /// Format: [documentId, "incremental", changeHash]
  /// </summary>
  /// <param name="documentId">The document identifier.</param>
  /// <param name="changeHash">The hash of the incremental change (typically from document heads).</param>
  /// <returns>A storage key for the incremental change.</returns>
  public static StorageKey DocumentIncremental(string documentId, string changeHash)
  {
    return new StorageKey(new[] { documentId, "incremental", changeHash });
  }

  /// <summary>
  /// Creates a storage key for document sync state.
  /// Format: [documentId, "sync-state", storageId]
  /// </summary>
  /// <param name="documentId">The document identifier.</param>
  /// <param name="storageId">The storage or peer identifier.</param>
  /// <returns>A storage key for the sync state.</returns>
  public static StorageKey DocumentSyncState(string documentId, string storageId)
  {
    return new StorageKey(new[] { documentId, "sync-state", storageId });
  }

  /// <summary>
  /// Creates a generic storage key.
  /// Format: [namespace, key]
  /// </summary>
  /// <param name="namespace">The namespace for organizing keys.</param>
  /// <param name="key">The key within the namespace.</param>
  /// <returns>A generic storage key.</returns>
  public static StorageKey Generic(string @namespace, string key)
  {
    return new StorageKey(new[] { @namespace, key });
  }

  /// <summary>
  /// Converts the storage key to a debug-friendly string representation.
  /// Components are joined with forward slashes.
  /// </summary>
  /// <returns>A string representation of the key.</returns>
  public string ToDebugString()
  {
    return Components == null || Components.Count == 0
      ? string.Empty
      : string.Join("/", Components);
  }

  /// <summary>
  /// Determines whether this storage key starts with the specified prefix.
  /// Used for hierarchical key filtering.
  /// </summary>
  /// <param name="prefix">The prefix to check.</param>
  /// <returns>True if this key starts with the prefix; otherwise, false.</returns>
  public bool StartsWith(StorageKey prefix)
  {
    // ReSharper disable once ConditionIsAlwaysTrueOrFalseAccordingToNullableAPIContract
    if(prefix.Components == null || prefix.Components.Count == 0)
      return true;

    if(Components == null || Components.Count < prefix.Components.Count)
      return false;

    for(int i = 0; i < prefix.Components.Count; i++)
    {
      if(Components[i] != prefix.Components[i])
        return false;
    }

    return true;
  }

  /// <summary>
  /// Returns a string representation of this storage key.
  /// </summary>
  /// <returns>A string representation of the key.</returns>
  public override string ToString() => ToDebugString();
}

